Translate("deDE", "the-hinterlands", {
	title = "Hinterland",
	aliases = { "das Hinterland" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Hinterland ist ein wildes Land aus grünen Hügeln, tiefen Wäldern und hohen Klippen, das nordöstlich des {link:arathi-highlands}Arathihochlands{/link} und östlich des {link:hillsbrad-foothills}Vorgebirges von Hillsbrad{/link} liegt. Wenige Straßen durchqueren es, und noch weniger Höfe. Seit Tausenden von Jahren gehört es den Waldtrollen, {link:trolls}Trollen{/link}, deren Tempel und Stufenstädte noch immer {link:razorfen-downs}die Hügel{/link} krönen. Auf einem Felsen im äußersten Westen steht {link:aerie-peak}Aerie Peak{/link}, die Heimat der {link:dwarves}Zwerge{/link} des {red:wildhammer-clan}Wildhammerklans{/red} und ihrer Greifen. Im äußersten Südosten, am Meer, halten die Revantusktrolle ein Dorf für die {link:horde}Horde{/link}. Dazwischen liegt ein Land im Krieg mit sich selbst: drei Trollstämme, die nichts als ihr Blut teilen, eine Hütte von {link:high-elves}Hochelfen{/link} fern der Heimat, und im Nordosten ein großer Baum, an dem die grünen Drachkin Wache halten.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet, wann die ersten {link:trolls}Trolle{/link} in diesen Hügeln bauten. Bekannt ist, dass die Wälder des Nordens einst zum Reich der Amani gehörten, dem Reich der Waldtrolle, und dass die Amani den {link:high-elves}Elfen{/link}, die sich in den Landen jenseits davon niederließen, nie vergaben. Die verfallenen Städte des Hinterlands sind Trollwerk, und ihre Altäre sind älter als jedes Menschenkönigreich. Die {link:dwarves}Zwerge{/link} kamen viel später. Nach dem Krieg der drei Hämmer verließ der Wildhammerklan die entweihten Hallen von {link:grim-batol}Grim Batol{/link} und schuf sich in {link:aerie-peak}Aerie Peak{/link} eine neue Heimat. Dort, im Hochland der Trolle, zähmten sie die wilden Greifen und lernten zu fliegen.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Das Hinterland hat keinen alleinigen Herrn. Die Wildhammer halten {link:aerie-peak}Aerie Peak{/link} unter ihrem Hochthan, {link:falstad-wildhammer}Falstad Wildhammer{/link}. Durch ihr Blut sind sie Verbündete von {link:ironforge}Ironforge{/link}, doch sie bestehen darauf, kein Teil der {link:alliance}Allianz{/link} zu sein und dass ihre Freundschaft durch Taten verdient werden muss. Die Revantusktrolle halten ihr Dorf an der Ostküste im Namen der {link:horde}Horde{/link}, und sie hassen die Wildhammer bitterlich. Die {red:vilebranch-trolls}Vilebranch{/red} beherrschen von ihren Tempeln aus den Süden und den Nordosten. Sie essen das Fleisch anderer {link:trolls}Trolle{/link} und opfern Gefangene dem Blutgott {link:hakkar}Hakkar{/link}. Die {link:witherbark-trolls}Witherbark{/link} halten den Südwesten, wo sie einem eigenen Spinnengott dienen. Die Schlammwesen des alten Hordelagers am {link:skulk-rock}Skulk Rock{/link} haben sich durch die Flusstäler ausgebreitet, und Wölfe, Eulenbestien und wilde Greifen jagen alles, was sich bewegt.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:dwarves}Zwerge{/link} der Wildhammer.{/b} Sie leben mit ihren Greifen in {link:aerie-peak}Aerie Peak{/link}. Sie sind stolz, laut und leidenschaftlich unabhängig, und sie erinnern sich an altes Unrecht länger als ihre Vettern in {link:ironforge}Ironforge{/link}.
• {b}Die Revantusktrolle.{/b} Waldtrolle der {link:horde}Horde{/link}, die ein Dorf am Meer halten und die Vilebranch ohne Gnade bekämpfen.
• {b}Die Vilebranchtrolle.{/b} Der größte und wildeste Stamm des Landes. Ihre {link:capital-city}Hauptstadt{/link} ist {link:jintha-alor}Jintha'Alor{/link}, wo ihre Priesterin Opfer für {link:hakkar}Hakkar{/link} vorbereitet.
• {b}Die {link:witherbark-trolls}Witherbarktrolle{/link}.{/b} Sie hausen in den Dörfern des Südwestens und in {link:shadra-alor}Shadra'Alor{/link}. Einst kämpften sie an der Seite der Horde, dann wandten sie sich gegen sie.
• {b}Die {link:high-elves}Hochelfen{/link} von {link:quel-danil-lodge}Quel'Danil{/link}.{/b} Waldläufer und Späher der Highvale halten im Westen, nahe den Zwergen, eine Jagdhütte.
• {b}Die grünen Drachkin.{/b} In {link:seradane}Seradane{/link} im Nordosten bewachen Drachenbrut und Drachen einen großen Baum und dulden niemanden in seiner Nähe.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Das Zeitalter der Amani.{/b} In vergangenen Zeitaltern beherrschten die Waldtrolle diese Hügel als Teil eines großen Reiches. Die {link:troll-wars}Trollkriege{/link} brachen ihre Macht, doch die {link:trolls}Trolle{/link} gingen nie fort.
• {b}Die drei Hämmer.{/b} Nach dem Krieg der drei Klans verließen die Wildhammer {link:grim-batol}Grim Batol{/link} und ließen sich in {link:aerie-peak}Aerie Peak{/link} nieder. Sie wurden die Greifenreiter des Nordens.
• {b}Der Zweite Krieg.{/b} Als die {link:horde}Horde{/link} der {link:orcs}Orcs{/link} nach Norden marschierte, schlossen sich ihr die Amanitrolle unter {red:zul-jin}Zul'jin{/red} an, in der Hoffnung, {link:quel-thalas}Quel'Thalas{/link} niederzubrennen. Die Wildhammer flogen für die {link:alliance}Allianz{/link} gegen sie. Die Horde hielt eine Zeit lang Stellungen im Hinterland, darunter das Lager am {link:skulk-rock}Skulk Rock{/link}. Am Ende gab sie sie auf.
• {b}Die neue Horde.{/b} Unter {link:thrall}Thrall{/link} fand die Horde erneut Freunde unter den Waldtrollen. Die {link:revantusk-village}Revantusk{/link} schlossen sich ihr an. Die {link:witherbark-village}Witherbark{/link} kämpften zuerst an ihrer Seite und verrieten sie dann, und die {link:darkspear-trolls}Darkspear{/link} haben zur Antwort grimmige Botschaften nach Norden geschickt.
• {b}Die Gegenwart.{/b} Nun warten die Revantusk auf Zul'jins Rückkehr, die Vilebranch nähren ihren {link:hakkar}Blutgott{/link}, und die {link:dwarves}Zwerge{/link} von Aerie Peak zählen jeden Greifen, den sie verlieren.]=],
		},
		{
			title = "Überlieferungen der Hügel",
			text = [=[• Die {link:revantusk-village}Revantusk{/link} sagen, die drei Trollstämme des Hinterlands hätten nur zweierlei gemein: Sie sind {link:trolls}Trolle{/link}, und sie leben im Hinterland.
• Wer in {link:aerie-peak}Aerie Peak{/link} neu ist und die Wildhammer "{link:alliance}Allianz{/link}" nennt, wird berichtigt, laut und auf der Stelle.
• Ein altes Rätsel, weit entfernt an den Küsten des Schlingendorntals gefunden, spricht von einem Schatz, der unter dem Wasser am Fuß der großen Fälle an der Küste des Hinterlands verborgen liegt.
• Ein betrunkener Greifenreiter aus Aerie Peak stürzte einst von seinem Reittier in den versunkenen Tempel der Atal'ai in den {link:swamp-of-sorrows}Sümpfen des Elends{/link} und überlebte, um die Geschichte für den Preis eines Getränks zu erzählen.]=],
		},
	},
})

Translate("deDE", "aerie-peak", {
	title = "Aerie Peak",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Aerie Peak ist die Festung der {link:dwarves}Zwerge{/link} des {red:wildhammer-clan}Wildhammerklans{/red}, errichtet auf einem Felsen am Westrand des Hinterlands. Sein Herz ist Burg Wildhammer, wo der Hochthan Hof hält, und darüber die große Voliere, in der die Greifen des Klans geboren, aufgezogen und abgerichtet werden. Die Stadt hat ein Gasthaus, Schmiede, Lederverarbeiter und in ihrer Mitte einen Brunnen. Sie ist ein lauter, stolzer und harter Ort. Fremde sind erst willkommen, wenn sie sich bewiesen haben, und die {link:trolls}Trolle{/link} des Ostens haben dafür gesorgt, dass kein Wildhammer je ohne eine Axt in Reichweite schläft.]=],
		},
	},
})

Translate("deDE", "revantusk-village", {
	title = "Revantusk",
	aliases = { "Dorf Revantusk" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Dorf Revantusk liegt an der Südostküste des Hinterlands, wo der Wald auf das Meer trifft. Es ist die Heimat der Revantusktrolle, eines Stammes von Waldtrollen, der der {link:horde}Horde{/link} dient. Pfahlhütten, Fischerboote und ein Horst für Windreiter drängen sich auf einem schmalen Streifen zwischen den Klippen und dem Wasser. Das Dorf wurde von den Vilebranch überfallen und hat Krieger an die Wölfe und Greifen der Wildnis verloren. Seine Bewohner haben mit Kopfgeldern, Blut und einer langen Liste von Beschwerden gegen die {link:dwarves}Zwerge{/link} von {link:aerie-peak}Aerie Peak{/link} geantwortet.]=],
		},
	},
})

Translate("deDE", "quel-danil-lodge", {
	title = "Die Quel'Danil-Hütte",
	aliases = { "Quel'Danil", "Quel'Danil-Hütte" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Quel'Danil-Hütte ist eine Jagdhütte der {link:high-elves}Hochelfen{/link}, erbaut zwischen den Bäumen des westlichen Hinterlands, ein kurzes Stück östlich von {link:aerie-peak}Aerie Peak{/link}. Waldläufer, Späher, Scharfschützen und Kundschafter der Highvale halten dort Wache. Sie sind fern von {link:quel-thalas}Quel'Thalas{/link}, und in den Wildhammern haben sie Freunde gefunden. Die {link:trolls}Trolle{/link} des Landes sind ihre Feinde. Die {link:revantusk-village}Revantusk{/link} sehen in den Elfen den Beweis, dass die {link:dwarves}Zwerge{/link} neue Bündnisse schmieden, und {link:witherbark-village}Witherbark{/link}, die den Elfen in die Hände fallen, werden als Gefangene in der Hütte gehalten.]=],
		},
	},
})

Translate("deDE", "shindigger-s-camp", {
	title = "Shindiggers Lager",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Shindiggers Lager ist ein kleines Lager aus Fässern und Kochfeuern im westlichen {link:the-hinterlands}Hinterland{/link}, östlich von {link:aerie-peak}Aerie Peak{/link} und nahe der {link:quel-danil-lodge}Quel'Danil-Hütte{/link}. Es gehört {link:rhapsody-shindigger}Rhapsody Shindigger{/link}, einst dem besten Greifenreiter der Voliere, der hier sein eigenes Gebräu braut, seit die {link:dwarves}Zwerge{/link} ihn entlassen haben. Er trinkt nicht allein. Ein {link:high-elves}Hochelf{/link} namens {link:gilveradin-sunchaser}Gilveradin Sunchaser{/link}, der edlen Wein über alle Sachen und Königreiche stellt, hat neben ihm sein Lager aufgeschlagen.]=],
		},
	},
})

Translate("deDE", "skulk-rock", {
	title = "Skulk Rock",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Skulk Rock ist eine Höhle mit einem verfallenen Lager in der Mitte des Hinterlands, am Oberlauf eines Flusses. Die {link:horde}Horde{/link} hatte hier einst einen Stützpunkt und gab den Ort vor langer Zeit auf. Die Kisten, die sie zurückließ, enthalten noch immer Flaschen mit {link:the-hinterlands}Hinterland{/link}-Honigkräusel, einem Getränk, das man nirgends mehr kaufen kann. Jetzt haben grüne Schlämme und Jadeschlammwesen die Ruinen überrannt, und die Geschichten sagen, dass irgendein Meisterschlamm sie anführt. Die Wildhammer wollen den Ort gesäubert haben, denn sie haben Pläne damit. In der Nähe fand man einst eine seltsame, zerstörte Metallapparatur gnomischer Bauart.]=],
		},
	},
})

Translate("deDE", "jintha-alor", {
	title = "Jintha'Alor",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Jintha'Alor ist die {link:capital-city}Hauptstadt{/link} der {red:vilebranch-trolls}Vilebranchtrolle{/red}. Sie erhebt sich im Süden des Hinterlands als große steinerne Stufenstadt und steigt Terrasse um Terrasse zu einem Amphitheater auf ihrem Gipfel empor. {link:oben-rageclaw}Oben{/link} herrscht die {link:vile-priestess-hexx}Verderbte Priesterin Hexx{/link}, bewacht von den Aman'zasi. Überall in der Stadt stehen Gefäße mit verdorbenem Blut, und ihre dunkle Macht treibt die Vilebranch in den Wahnsinn. Gefangene werden hierher gebracht, um {link:hakkar}Hakkar{/link} geopfert zu werden. Eine Abfallgrube voller Schlammwesen und eine Wolfshöhle warten nahe dem Gipfel auf die Überreste. In einer Höhle hinter dem Amphitheater, so heißt es, liegt ein uraltes Ei aus den Tagen, als die {link:trolls}Trolle{/link} über Reiche herrschten.]=],
		},
	},
})

Translate("deDE", "the-altar-of-zul", {
	title = "Der Altar von Zul",
	aliases = { "Altar von Zul" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Altar von Zul ist ein Trolltempel am Westrand des Landes der Vilebranch, nordwestlich von {link:jintha-alor}Jintha'Alor{/link}. Seine Stufen steigen zu einem hohen Altar empor, an dem die Vilebranch ihre Opfer darbringen. Zwei Hüter des Stammes, Qiaga und Morta'gya, versehen ihn. Als der junge Greif Sharpbeak verschwand, fürchteten die {link:dwarves}Zwerge{/link} von {link:aerie-peak}Aerie Peak{/link}, er sei hierher verschleppt worden. Sie waren erleichtert, als er nicht auf dem Altar gefunden wurde, denn sie wussten, was die Vilebranch dort tun.]=],
		},
	},
})

Translate("deDE", "shadra-alor", {
	title = "Shadra'Alor",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Shadra'Alor ist ein Trolltempel tief im südwestlichen {link:the-hinterlands}Hinterland{/link}, im Reich der {link:witherbark-trolls}Witherbark{/link}. Er ist der Sitz ihres Spinnengottes {link:shadra}Shadra{/link}, und in seinen Wäldern wimmelt es von ihren Kindern. Die {link:witherbark-village}Witherbark{/link} sammeln ihr Gift und bewahren es in ihren Dörfern in Flaschen auf. Im Herzen des Tempels steht ein Altar, an dem die Göttin selbst herbeigerufen werden kann, wenn man ihren wahren Namen ausspricht. Nahe dem Tempel lebt ein {link:atal-ai-exile}Verbannter der Atal'ai{/link}, ein Priester, den sein eigenes Volk verstoßen hat und der bei den Witherbark eine bittere Zuflucht gefunden hat.]=],
		},
	},
})

Translate("deDE", "hiri-watha-and-zun-watha", {
	title = "Hiri'watha und Zun'watha",
	aliases = { "Hiri'watha", "Zun'watha" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hiri'watha und Zun'watha sind die beiden Dörfer der {link:witherbark-trolls}Witherbarktrolle{/link} im Südwesten des Hinterlands. Sie sind kleiner als die Tempelstädte der Vilebranch, aber nicht weniger gefährlich. In ihren Hütten stehen Käfige für Gefangene und Flaschen mit grünem Gift von den Spinnen von {link:shadra-alor}Shadra'Alor{/link}. Die {link:witherbark-village}Witherbark{/link} kämpften einst an der Seite der {link:horde}Horde{/link} und verrieten sie dann, und die {link:darkspear-trolls}Darkspear{/link} des Schlingendorntals haben es nicht vergessen. Ihr Gesandter {link:nimboya}Nimboya{/link} hat seinen Spieß nach Norden geschickt, damit er in einem dieser Dörfer steht, gekrönt mit Schädeln der Witherbark.]=],
		},
	},
})

Translate("deDE", "agol-watha-and-shaol-watha", {
	title = "Agol'watha und Shaol'watha",
	aliases = { "Agol'watha", "Shaol'watha" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Agol'watha und Shaol'watha sind zwei Tempel der {red:vilebranch-trolls}Vilebranch{/red} im Nordosten des Hinterlands. Ihre Skalpjäger und Wahrsager versammeln sich dort, und von dort ziehen ihre Plünderer gegen das {link:revantusk-village}Dorf Revantusk{/link} aus. Nach einem solchen Überfall sah man das gestohlene Werkzeug des Schmieds von Revantusk nahe diesen Tempeln. Für die Revantusk sind die beiden Tempel Nester von Menschenfressern, und ihre Jäger kehren mit Geschichten von dort zurück, die sie den Jungen nicht erzählen.]=],
		},
	},
})

Translate("deDE", "seradane", {
	title = "Seradane",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Seradane liegt im äußersten Nordosten des Hinterlands, in einer hochgelegenen Senke jenseits der Trolltempel. Dort erhebt sich ein großer Baum. Er ist einer der wenigen Orte der Welt, an denen die wache Welt den {link:emerald-dream}Smaragdgrünen Traum{/link} berührt, und die Druiden zählen ihn zu den vier solchen Bäumen auf {link:azeroth}Azeroth{/link}. Grüne Drachenbrut bewacht seine Wurzeln, und große grüne Drachen wachen über seine Krone. Sie verhandeln nicht mit jenen, die sich nähern, und weder Troll noch {link:dwarves}Zwerg{/link} steigt freiwillig in ihre Senke hinauf.]=],
		},
	},
})

Translate("deDE", "the-overlook-cliffs", {
	title = "Die Aussichtsklippen",
	aliases = { "Aussichtsklippen" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Aussichtsklippen sind der hohe Ostrand des Hinterlands, wo das Land steil ins Meer abfällt. Wasserfälle stürzen von den Hügeln in die Wellen, und kleine Inseln liegen dicht vor der Küste. Der gefangene {link:witherbark-village}Witherbark{/link} {link:rin-ji}Rin'ji{/link} versteckte auf einer dieser Inseln eine Tafel seines Volkes. Die gnomischen Ingenieure von {link:booty-bay}Booty Bay{/link} wählten einst die Küste jenseits der Klippen als sicheren Ort, um eine abgestürzte Flugmaschine heimzurufen. Ein altes Rätsel aus fernen Landen spricht von einem Schatz unter dem Wasser am Fuß der großen Fälle.]=],
		},
	},
})

Translate("deDE", "falstad-wildhammer", {
	title = "Falstad Wildhammer",
	subtitle = "Hochthan der Wildhammer",
	found = "Burg Wildhammer, Aerie Peak",
	hint = "Sprecht mit dem Hochthan in der Burg von Aerie Peak.",
	allegiance = "Wildhammerklan",
	aliases = { "Falstad" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Falstad Wildhammer ist der Hochthan der {link:dwarves}Zwerge{/link} des {red:wildhammer-clan}Wildhammerklans{/red}. Von seiner Burg in {link:aerie-peak}Aerie Peak{/link} aus herrscht er über den Klan, seine Reiter und seine Greifen. Seine Geduld ist kurz und sein Gedächtnis lang. Er hat keine Zeit für Geschwätz, während {link:trolls}Trolle{/link} gegen seine Grenzen drängen, und das sagt er offen. Doch die Stärke des Klans ruht auf seinem Urteil, und jeder Auftrag, der Aerie Peak erreicht, geht zuerst durch seine Halle.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Falstad führt den einzigen Zwergenklan, der {link:magni-bronzebeard}Magni Bronzebeard{/link} keine Rechenschaft schuldet. Die Wildhammer sind mit {link:ironforge}Ironforge{/link} verwandt, und sie flogen im {link:second-war}Zweiten Krieg{/link} an der Seite der {link:alliance}Allianz{/link}. Dennoch gehen sie ihre eigenen Wege. Unter Falstad steht {link:aerie-peak}Aerie Peak{/link} allein in den Hügeln der {link:trolls}Trolle{/link}, und seine Bewohner bestehen darauf, kein Teil der Allianz zu sein. Freundschaft mit ihnen ist kein Vertrag. Sie ist eine Schuld aus Taten, verdient Troll um Troll.

Für die Lande um ihn herum macht Falstads Herrschaft den Unterschied zwischen einem Grenzland und einer Wildnis. Die Revantusktrolle nennen sein Volk Abschaum und pflanzen blutige Speere in seiner Stadt auf. Die Vilebranch stehlen seine Greifen. Die Schlammwesen von {link:skulk-rock}Skulk Rock{/link} stehen zwischen seinen Reitern und dem Herzen des Landes. Falstad begegnet allem mit derselben Antwort: Die Wildhammer waren schon vorher hier, und sie werden auch danach noch hier sein.]=],
		},
		{
			title = "Taten",
			text = [=[• Er herrscht als Hochthan über {link:aerie-peak}Aerie Peak{/link} und den Wildhammerklan.
• Er hält den Klan unabhängig, durch Blut mit den Zwergen von {link:ironforge}Ironforge{/link} verbündet, doch an keinen König gebunden.
• Er hält seine Grenzen gegen drei Trollstämme zugleich.
• Fremde, die die Reiter der Voliere suchen, schickt er weiter zu seinem {link:gryphon-master-talonaxe}Greifenmeister Talonaxe{/link}.
• Er heißt die {link:high-elves}Hochelfen{/link} von {link:quel-danil-lodge}Quel'Danil{/link} als Freunde willkommen, zum Zorn der {link:revantusk-village}Revantusk{/link}.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Geschichten vom Krieg gegen die {link:dragonmaw-clan}Dragonmaw{/link} erzählen von einem Greifenreiter der Wildhammer namens Falstad, der in den Jahren nach dem Zweiten Krieg über {link:grim-batol}Grim Batol{/link} kämpfte. Ob dieser Reiter und der Hochthan von {link:aerie-peak}Aerie Peak{/link} ein und derselbe sind, sagt keine für diesen Eintrag herangezogene Chronik deutlich. Wenig mehr ist darüber geschrieben, wie Falstad zur Herrschaft über seinen Klan kam.]=],
		},
	},
	chapters = {
		{
			title = "Trolle an allen Ecken",
			hint = "Kommt im Auftrag der Forscherliga nach Aerie Peak.",
			text = [=[Der {link:dwarves}Zwerg{/link}, der mit einer Frage von {link:brohann-caskbelly}Brohann Caskbelly{/link} von der {link:explorers-league}Forscherliga{/link} nach {link:aerie-peak}Aerie Peak{/link} kam, fand den Hochthan nicht in der Stimmung für Besucher. Aus jedem Winkel der Hügel kamen {link:trolls}Trolle{/link} hervor, und ein Than im Krieg hat wenig Zeit für alte Geschichten über einen verschollenen Reiter. Falstad hörte die Frage an, murrte über den Fremden, der sie stellte, und schickte die Angelegenheit dorthin, wo sie hingehörte: zum Meister der Voliere.]=],
		},
		{
			title = "Taten, nicht Worte",
			hint = "Verdient Euch den Respekt der Wildhammer von Aerie Peak.",
			text = [=[Unter Falstads Herrschaft misst der Klan einen Fremden an dem, was er tut. Die Trollhalsketten, die in seine Halle gebracht werden, und die aus {link:skulk-rock}Skulk Rock{/link} beseitigten Schlammwesen sind die einzige Sprache der Freundschaft, der die Wildhammer trauen. Jede Tat wird verzeichnet. Mit der Zeit merken jene, die dabeibleiben, dass sich die Tore von {link:aerie-peak}Aerie Peak{/link} ihnen ein wenig weiter öffnen.]=],
		},
	},
	mentions = {
		{
			text = [=[Ins {link:the-hinterlands}Hinterland{/link}, eine Frage der {link:explorers-league}Forscherliga{/link}]=],
		},
		{ text = "{link:gryphon-master-talonaxe}Greifenmeister Talonaxe{/link}" },
		{
			text = [=[Kopfgeld für Trollhalsketten, der Preis der Freundschaft der Wildhammer]=],
		},
		{ text = "Säuberung von {link:skulk-rock}Skulk Rock{/link}" },
		{
			text = [=[Die letzte Botschaft an die Wildhammer, ein Speer an seinem Brunnen]=],
		},
	},
	bonds = {
		{ id = "gryphon-master-talonaxe", name = "Greifenmeister Talonaxe", note = "Meister seiner Voliere" },
		{ id = "fraggar-thundermantle", name = "Fraggar Thundermantle", note = "prüft die neuen Freunde des Klans" },
		{ id = "brohann-caskbelly", name = "Brohann Caskbelly", note = "schickte einen Fremden in seine Halle" },
		{ id = "primal-torntusk", name = "Primal Torntusk", note = "führt die Trolle an, die seinen Klan hassen" },
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "König seiner Verwandten in Ironforge" },
	},
})

Translate("deDE", "gryphon-master-talonaxe", {
	title = "Greifenmeister Talonaxe",
	subtitle = "Meister der Voliere von Aerie Peak",
	found = "Die Voliere von Aerie Peak",
	hint = [=[Steigt zur Voliere von Aerie Peak hinauf und sprecht mit ihrem Meister.]=],
	allegiance = "Wildhammerklan",
	aliases = { "Talonaxe" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Greifenmeister Talonaxe hütet die große Voliere von {link:aerie-peak}Aerie Peak{/link}. Er kennt jeden Greifen in den Schwärmen des Klans und jeden Reiter, der je einen geflogen hat. Er erinnert sich an ihre Namen lange, nachdem andere sie vergessen haben, und er hat eine Schwäche für die {link:explorers-league}Forscherliga{/link}, denn sein eigener Vater war unter den Zwergen, die {link:uldaman}Uldaman{/link} als Erste freilegten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Die Greifen sind die Stärke der Wildhammer, und Talonaxe ist ihr Hüter. Wenn ein Greif verloren geht, spürt es der ganze Klan. Als der Erbe des größten Greifen der Voliere verschwand, war es Talonaxe, der nicht ruhte, bis der Junge gefunden war. Seine Geschichte zeigt, wie eng das Schicksal der {link:dwarves}Zwerge{/link} mit dem Schicksal ihrer Tiere verbunden ist.]=],
		},
		{
			title = "Taten",
			text = [=[• Er richtet die Greifen von {link:aerie-peak}Aerie Peak{/link} ab und teilt ihnen ihre Reiter zu.
• Er lieh einst seinen besten Reiter, {link:rhapsody-shindigger}Rhapsody Shindigger{/link}, dem Forscher {link:brohann-caskbelly}Brohann Caskbelly{/link} für einen Flug über die {link:swamp-of-sorrows}Sümpfe des Elends{/link}.
• Er entließ Rhapsody, als diesen nach jenem Flug der Trunk gepackt hatte.
• Er leitete die Suche nach Sharpbeak, von den Käfigen der {link:witherbark-village}Witherbark{/link} bis zum {link:the-altar-of-zul}Altar von Zul{/link}.
• Er schickte nach einem Wahrsager der Wildhammer in den {link:blasted-lands}Verwüsteten Landen{/link}, als alle anderen Suchen gescheitert waren.]=],
		},
	},
	chapters = {
		{
			title = "Der Reiter, der stürzte",
			hint = [=[Erfahrt vom Greifenmeister, was aus dem Reiter wurde, der mit Brohann geschickt wurde.]=],
			text = [=[Talonaxe erinnerte sich sofort an den Flug. Er hatte seinen besten Reiter geschickt, um mit {link:brohann-caskbelly}Brohann{/link} über den Sumpf zu fliegen, auf der Suche nach einem versunkenen Tempel. Der Reiter war {link:rhapsody-shindigger}Rhapsody Shindigger{/link}, und niemand in der Voliere konnte fliegen wie er. Doch Rhapsody kehrte erschüttert und durstig von diesem Flug zurück, und sein Durst wuchs nur noch. Am Ende musste der Meister der Voliere ihn fortschicken.]=],
		},
		{
			title = "Der verlorene Erbe",
			hint = [=[Durchsucht die Trolldörfer und den Altar von Zul nach einem vermissten jungen Greifen.]=],
			text = [=[Sharpbeak, der Erbe des mächtigsten Greifen der Voliere, verschwand, als er mit seinen Eltern jagte. Talonaxe war sicher, dass {link:trolls}Trolle{/link} ihn geholt hatten. Die Käfige in den Dörfern der {link:witherbark-village}Witherbark{/link} wurden durchsucht und leer gefunden. Als Nächstes wurde der {link:the-altar-of-zul}Altar von Zul{/link} durchsucht, wo die Vilebranch ihre Opfer darbringen. Auch dort war der junge Greif nicht, und Talonaxe wusste nicht, ob er trauern oder sich freuen sollte.]=],
		},
		{
			title = "Eine Feder und ein Wahrsager",
			hint = [=[Bringt eine Feder aus Sharpbeaks Nest zum Wahrsager von Nethergarde.]=],
			text = [=[Als jede Spur erkaltet war, wandte sich Talonaxe an {link:thadius-grimshade}Thadius Grimshade{/link}. Grimshade hatte {link:aerie-peak}Aerie Peak{/link} vor Jahren verlassen, um dunkleres Wissen zu suchen, doch Talonaxe nannte ihn noch immer einen Wildhammer im Herzen. Eine Feder aus dem Nest, in dem der junge Greif geschlafen hatte, wurde zum Turm des Wahrsagers geschickt, damit er ihrem Faden zurück zu ihrem Besitzer folgen konnte.]=],
		},
		{
			title = "Der Käfig auf der Klippe",
			hint = [=[Bringt den jungen Greifen heim, den die Vilebranch gefangen halten.]=],
			text = [=[Grimshades Weissagung fand Sharpbeak in einem Käfig hoch auf einer Klippe bei {link:jintha-alor}Jintha'Alor{/link}. Der Schlüssel hing am Gürtel der Verderbten Priesterin {link:vile-priestess-hexx}Hexx{/link}. Die Wildhammer konnten es nicht ertragen. Die Priesterin fiel, der Käfig wurde geöffnet, und Sharpbeak flog heim zu seinen Eltern. Talonaxe sah zu, wie sie sich um ihr Junges kümmerten, und die Augen des alten Zwergs blieben nicht trocken.]=],
		},
	},
	mentions = {
		{ text = "Greifenmeister Talonaxe" },
		{ text = "{link:rhapsody-shindigger}Rhapsody Shindigger{/link}" },
		{ text = "Käfige der {link:witherbark-village}Witherbark{/link}" },
		{ text = "{link:the-altar-of-zul}Der Altar von Zul{/link}" },
		{ text = "{link:thadius-grimshade}Thadius Grimshade{/link}" },
		{ text = "Zurück ins {link:the-hinterlands}Hinterland{/link}" },
		{ text = "Sharpbeak retten" },
	},
	bonds = {
		{ id = "falstad-wildhammer", name = "Falstad Wildhammer", note = "sein Hochthan" },
		{ id = "rhapsody-shindigger", name = "Rhapsody Shindigger", note = "einst sein bester Reiter" },
		{ id = "sharpbeak", name = "Sharpbeak", note = "der verlorene Erbe der Voliere" },
		{ id = "thadius-grimshade", name = "Thadius Grimshade", note = "ein Wildhammer im Herzen" },
		{ id = "vile-priestess-hexx", name = "Verderbte Priesterin Hexx", note = "hielt den Schlüssel zu Sharpbeaks Käfig" },
		{ id = "brohann-caskbelly", name = "Brohann Caskbelly", note = "lieh sich seinen besten Reiter" },
	},
})

Translate("deDE", "fraggar-thundermantle", {
	title = "Fraggar Thundermantle",
	subtitle = "Wildhammer von Aerie Peak",
	found = "Aerie Peak",
	hint = [=[Sucht den Wildhammer, der in Aerie Peak den Wert von Fremden prüft.]=],
	allegiance = "Wildhammerklan",
	aliases = { "Fraggar" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Fraggar Thundermantle ist die Stimme des Stolzes der Wildhammer in {link:aerie-peak}Aerie Peak{/link}. Er will, dass jeder Fremde sofort eines begreift: Die Wildhammer sind kein Teil der {link:alliance}Allianz{/link}. Sie vertrauen Taten mehr als Worten, und sie haben keine Geduld mit jenen, die mit Gerede und sonst nichts zu ihnen kommen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Fraggar entscheidet, wer ein Freund des Klans ist. Er stellt die Aufgaben, mit denen Außenstehende sich beweisen, und er führt die Rechnung. Durch ihn wollen die Wildhammer ihre Reichweite tiefer ins Land der {link:trolls}Trolle{/link} ausdehnen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er bezahlt für die Stammeshalsketten der {link:trolls}Trolle{/link}, die die Hänge verstopfen.
• Er schickt Trupps aus, um die Schlammwesen aus {link:skulk-rock}Skulk Rock{/link} zu entfernen, wo der Klan eigene Pläne hat.]=],
		},
	},
	mentions = {
		{ text = "Säuberung von {link:skulk-rock}Skulk Rock{/link}" },
		{ text = "Kopfgeld für Trollhalsketten" },
		{ text = "Kopfgeld für Trollhalsketten, immer wieder" },
	},
	bonds = {
		{ id = "falstad-wildhammer", name = "Falstad Wildhammer", note = "sein Hochthan" },
	},
})

Translate("deDE", "agnar-beastamer", {
	title = "Agnar Beastamer",
	subtitle = "Tierführer von Aerie Peak",
	found = "Aerie Peak",
	hint = "Sucht den Meistertierführer von Aerie Peak auf.",
	allegiance = "Wildhammerklan",
	aliases = { "Agnar" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Agnar Beastamer ist ein Meister im Umgang mit Tieren in {link:aerie-peak}Aerie Peak{/link}. Sein Volk zieht Greifen auf, doch Agnars Wissen reicht weiter. Er weiß, wie man ein seltenes Ei zum Schlüpfen bringt, was ein neugeborenes Geschöpf fressen soll und wie man es an den bindet, der für es sorgen wird.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Agnar bewahrt die Gabe der Wildhammer, Seite an Seite mit wilden Geschöpfen zu leben. Selbst ein Feendrache aus den Elfenwäldern ist nicht jenseits seiner Fürsorge.]=],
		},
		{
			title = "Taten",
			text = [=[• Er pflegte ein zerbrechliches Ei eines Irrlichtflitzers, eines selten gesehenen Feendrachen, bis es schlüpfte.
• Er ließ Flanken der Silvermanewölfe holen, denn er weiß, dass Irrlichtflitzer sowohl Fleisch als auch Grünzeug fressen.
• Er übergab das Junge seinem Hüter, damit es seinen Hüter als Elternteil erkennt.]=],
		},
	},
	mentions = {
		{ text = "Das neueste Familienmitglied" },
		{ text = "Futter für das Baby" },
		{ text = "Eltern werden" },
	},
	bonds = {
		{ id = "gryphon-master-talonaxe", name = "Greifenmeister Talonaxe", note = "hütet die Greifen derselben Stadt" },
	},
})

Translate("deDE", "rhapsody-shindigger", {
	title = "Rhapsody Shindigger",
	subtitle = "Ehemaliger Greifenreiter von Aerie Peak",
	found = "Shindiggers Lager",
	hint = [=[Sucht den ehemaligen Greifenreiter, der östlich von Aerie Peak sein eigenes Gebräu braut.]=],
	allegiance = "Wildhammerklan (entlassen)",
	aliases = { "Rhapsody" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Rhapsody Shindigger war einst der beste Greifenreiter von {link:aerie-peak}Aerie Peak{/link}. Er flog mit dem Forscher {link:brohann-caskbelly}Brohann Caskbelly{/link} über die {link:swamp-of-sorrows}Sümpfe des Elends{/link}, auf der Suche nach einem versunkenen Tempel. Nach diesem Flug verfiel er dem Trunk, und die Voliere entließ ihn. Jetzt betreibt er ein eigenes Braulager, und jeder seiner Sätze wird von Schluckauf unterbrochen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Rhapsody allein kannte die Wahrheit, die {link:brohann-caskbelly}Brohann{/link} suchte. Der Tempel der Atal'ai liegt unter dem Sumpf, und er hatte ihn mit eigenen Augen gesehen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er trank vor dem Flug über den Sumpf ein ganzes Fass Stout.
• Er stürzte von seinem Greifen ins Wasser, wurde hinabgezogen und fand sich in einem versunkenen Tempel unter Trollen wieder.
• Er entkam mit einem Bruchstück einer Tafel der Atal'ai.]=],
		},
	},
	chapters = {
		{
			title = "Ein kräftiger Schluck",
			hint = [=[Bringt dem ehemaligen Reiter, was er braucht, um seine Geschichte zu erzählen.]=],
			text = [=[Nüchtern wollte Rhapsody nicht vom Sumpf sprechen. Nur ein Trunk, gebraut aus Mägen und Lebern von Tieren aus dem fernen {link:kalimdor}Kalimdor{/link}, konnte ihm die Zunge lösen. Dann kam die Geschichte endlich heraus. Der Reiter war in den Sumpf gestürzt, in den Tempel der {link:temple-of-atal-hakkar}Atal'ai{/link} gesunken und mit einem Trollrelikt in der Hand wieder herausgeschwommen. Der Tempel, den {link:brohann-caskbelly}Brohann{/link} gesucht hatte, war echt.]=],
		},
	},
	mentions = {
		{ text = "Rhapsody Shindigger" },
		{ text = "Rhapsodys {link:kalimdor}Kalimdor{/link}-Cocktail" },
		{ text = "Rhapsodys Geschichte" },
	},
	bonds = {
		{ id = "gryphon-master-talonaxe", name = "Greifenmeister Talonaxe", note = "entließ ihn" },
		{ id = "brohann-caskbelly", name = "Brohann Caskbelly", note = "flog mit ihm über den Sumpf" },
		{ id = "gilveradin-sunchaser", name = "Gilveradin Sunchaser", note = "teilt sein Lager" },
	},
})

Translate("deDE", "gilveradin-sunchaser", {
	title = "Gilveradin Sunchaser",
	subtitle = "Hochelf des Hinterlands",
	found = "Shindiggers Lager",
	hint = [=[Sucht in einem Lager östlich von Aerie Peak den Hochelfen, der jeden Jahrgang am Geruch erkennt.]=],
	allegiance = "Keiner außer gutem Trunk",
	aliases = { "Gilveradin" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gilveradin Sunchaser ist ein {link:high-elves}Hochelf{/link}, der in einem Lager nahe der {link:quel-danil-lodge}Quel'Danil-Hütte{/link} lebt. Er kann jeden Wein und seinen Jahrgang allein am Geruch benennen. Er hat, sagt er, etwas gefunden, das jeden Vertrag und jede Grenze überwindet: starken Trunk. Er teilt ihn mit {link:orcs}Orc{/link} und {link:dwarves}Zwerg{/link} gleichermaßen, und er ist kein Freund der {link:alliance}Allianz{/link}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Gilveradin zeigt, dass nicht jeder Elf des Hinterlands der Hütte dient. Zu seinen alten Zechgenossen zählt er Goblins aus {link:orgrimmar}Orgrimmar{/link}, und er hat die leeren Flaschen und die Verpackung, die aus einem geborgenen Getränk einen Schatz machen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er verpackt den aus {link:skulk-rock}Skulk Rock{/link} geborgenen {link:the-hinterlands}Hinterland{/link}-Honigkräusel, gegen eine Gebühr, die in Kräusel bezahlt wird.
• Er schickt die Fässer weiter zu den Droffers, einer Bergerfamilie in {link:orgrimmar}Orgrimmar{/link}.]=],
		},
	},
	mentions = {
		{ text = "Kräuselbergung" },
		{ text = "Eine klebrige Angelegenheit" },
		{ text = "Kräusellieferung" },
	},
	bonds = {
		{ id = "rhapsody-shindigger", name = "Rhapsody Shindigger", note = "teilt sein Lager" },
	},
})

Translate("deDE", "rin-ji", {
	title = "Rin'ji",
	subtitle = "Gefangener der Witherbark",
	found = "Ein Gefangener in der Quel'Danil-Hütte",
	hint = [=[Sucht den Witherbarktroll, der in der Quel'Danil-Hütte gefangen gehalten wird.]=],
	allegiance = "Witherbarktrolle",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Rin'ji ist ein Troll der {link:witherbark-trolls}Witherbark{/link}, der seine Axt verlor und von den {link:high-elves}Hochelfen{/link} der {link:quel-danil-lodge}Quel'Danil-Hütte{/link} gefangen genommen wurde. Er fleht jeden Fremden, der in seine Nähe kommt, an, ihm bei der Flucht zu helfen. Im Gegenzug verspricht er ein Geheimnis, das weit im Osten an den {link:the-overlook-cliffs}Aussichtsklippen{/link} verborgen liegt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Das Geheimnis, das Rin'ji hütete, war eine Tafel mit den Zeichen seines Stammes. Sie gelangte zu den Gelehrten von {link:undercity}Undercity{/link}, und sie gefiel ihnen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er wurde aus der {link:quel-danil-lodge}Quel'Danil-Hütte{/link} befreit und floh in {link:razorfen-downs}die Hügel{/link}.
• Er versteckte eine Tafel der {link:witherbark-village}Witherbark{/link} auf einer kleinen, verlassenen Insel vor den {link:the-overlook-cliffs}Aussichtsklippen{/link}.]=],
		},
	},
	mentions = {
		{ text = "Rin'ji ist gefangen!" },
		{
			text = [=[Rin'jis Geheimnis, nach {link:undercity}Undercity{/link} gebracht]=],
		},
		{ text = "Orans Dankbarkeit" },
	},
	bonds = {
		{ id = "oran-snakewrithe", name = "Oran Snakewrithe", note = "las seine Tafel" },
	},
})

Translate("deDE", "atal-ai-exile", {
	title = "Verbannter der Atal'ai",
	subtitle = "Verstoßener Priester der Atal'ai",
	found = "Nahe Shadra'Alor, unter den Witherbark",
	hint = [=[Sucht den verstoßenen Priester, der nahe Shadra'Alor unter den Witherbark lebt.]=],
	allegiance = "Keine (von den Atal'ai verbannt)",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Verbannte der Atal'ai war einst ein Priester der Atal'ai, der Trollsekte des versunkenen Tempels in den {link:swamp-of-sorrows}Sümpfen des Elends{/link}. Als {link:jammal-an-the-prophet}der Prophet{/link} Jammal'an verkündete, die Beschwörung {link:hakkar}Hakkar{/link}s werde die Atal'ai unsterblich machen, mahnte dieser Priester zur Vorsicht. Dafür wurde er zum Ungläubigen erklärt und verstoßen. Das Urteil seines Volkes schickte ihn nach Norden, um unter den {link:witherbark-village}Witherbark{/link} zu leben, ein Schicksal, das die Atal'ai für schlimmer als den Tod halten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Der Verbannte ist eine seltene Stimme des Zweifels im Kult Hakkars. Er glaubt, dass Jammal'ans Prophezeiung sein Volk vernichten wird, und er kennt die Beschwörungsriten gut genug, um sie zu fürchten.]=],
		},
		{
			title = "Taten",
			text = [=[• Er warnte {link:jammal-an-the-prophet}Jammal'an{/link}, die Prophezeiung könnte nichts weiter als Manipulation sein.
• Er befand die Artefakte der Atal'ai, die man ihm aus dem Sumpf brachte, für harmlos, warnte aber davor, was das Ritual anrichten könnte, wenn es vollendet würde.
• Er sinnt auf Rache für seine Verbannung.]=],
		},
	},
	chapters = {
		{
			title = "Das Haupt des Propheten",
			hint = "Rächt den Verbannten an dem Propheten, der ihn verstieß.",
			text = [=[Der Verbannte wollte Jammal'ans Kopf. Er hoffte, sein Volk könnte frei sein, sobald {link:jammal-an-the-prophet}der Prophet{/link} fort wäre, und er selbst könnte heimkehren. Als die Tat vollbracht war, sprach er seinen Dank aus, und er trauerte. Jammal'ans falsche Visionen hatten die Atal'ai bereits ins Verderben geführt. Es gab keine Heimat mehr, zu der er zurückkehren konnte.]=],
		},
	},
	mentions = {
		{ text = "Der Verbannte der Atal'ai" },
		{ text = "Zurück zu Fel'Zerul" },
		{ text = "{link:jammal-an-the-prophet}Jammal'an der Prophet{/link}" },
	},
	bonds = {
		{ id = "fel-zerul", name = "Fel'Zerul", note = "schickte ihm die Artefakte der Atal'ai" },
	},
})

Translate("deDE", "sharpbeak", {
	title = "Sharpbeak",
	subtitle = "Erbe der Voliere von Aerie Peak",
	found = "Ein Käfig auf einer Klippe nahe Jintha'Alor",
	hint = [=[Sucht den jungen Greifen, den die Vilebranch in einem Käfig gefangen halten.]=],
	allegiance = "Wildhammerklan",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Sharpbeak ist ein junger Greif aus {link:aerie-peak}Aerie Peak{/link}, das Junge des mächtigsten Greifen der Voliere. Die {link:dwarves}Zwerge{/link} sagen, er sei dazu bestimmt, die nächste Generation ihrer Schwärme anzuführen. Während er mit seinen Eltern jagte, nahmen die {red:vilebranch-trolls}Vilebranch{/red} ihn gefangen und sperrten ihn in einen Käfig hoch auf einer Klippe über ihren Landen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Für die Wildhammer war der Verlust Sharpbeaks eine Wunde für den ganzen Klan. Die Stärke und der Geist ihrer Flotte, sagte {link:gryphon-master-talonaxe}Talonaxe{/link}, würden ohne ihn leiden.]=],
		},
		{
			title = "Taten",
			text = [=[• Er wurde von Trollen verschleppt und nahe {link:jintha-alor}Jintha'Alor{/link} eingesperrt.
• Er wurde befreit, nachdem die {link:vile-priestess-hexx}Verderbte Priesterin Hexx{/link} gefallen war, und kehrte zu seinen Eltern in der Voliere zurück.]=],
		},
	},
	mentions = {
		{ text = "Käfige der {link:witherbark-village}Witherbark{/link}" },
		{ text = "Sharpbeak retten" },
	},
