Translate("deDE", "vile-priestess-hexx", {
	title = "Verderbte Priesterin Hexx",
	subtitle = "Hohepriesterin der Vilebranch",
	found = "Der Gipfel von Jintha'Alor",
	hint = [=[Stellt Euch der Hohepriesterin, die über den Gipfel von Jintha'Alor herrscht.]=],
	allegiance = "Vilebranchtrolle",
	aliases = { "Hexx" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Verderbte Priesterin Hexx ist die Hohepriesterin der {red:vilebranch-trolls}Vilebranchtrolle{/red}. Mit ihren auserwählten Wachen, den Aman'zasi, herrscht sie über den Gipfel von {link:jintha-alor}Jintha'Alor{/link}. Ihre dunklen Webereien füllen überall in der Stadt Gefäße mit verdorbenem Blut, und durch sie treibt die Macht des Blutgottes {link:hakkar}Hakkar{/link} ihr Volk zu einer wahnsinnigen, todlosen Wildheit.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Hexx ist der Grund, warum die Vilebranch mehr sind als ein wilder Stamm. Durch sie sind sie zu Dienern Hakkars geworden und nehmen Gefangene aus jedem Volk des Hinterlands, um sie zu opfern. {link:dwarves}Zwerge{/link} wie {link:trolls}Trolle{/link} leiden unter ihrer Herrschaft. Sowohl {link:aerie-peak}Aerie Peak{/link} als auch das {link:revantusk-village}Dorf Revantusk{/link} haben ein Kopfgeld auf sie ausgesetzt. Die Revantusk warnen, dass selbst wenn sie fällt, eine andere an ihre Stelle treten wird.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie bereitete den Ältesten {link:primal-torntusk}Torntusk{/link} der {link:revantusk-village}Revantusk{/link} als Opfer für {link:hakkar}Hakkar{/link} vor.
• Sie hielt den Schlüssel zum Käfig von Sharpbeak, dem jungen Greifen aus {link:aerie-peak}Aerie Peak{/link}.
• Sie stärkte die Vilebranch mit dem verdorbenen Blut des gesichtslosen Gottes.
• Sie befehligt die Aman'zasi, die Elitewache von {link:jintha-alor}Jintha'Alor{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Die Priesterin des Blutgottes",
			hint = "Brecht die Macht der verdorbenen Gefäße von Jintha'Alor.",
			text = [=[Die {link:revantusk-village}Revantusk{/link} erfuhren, woher die Vilebranch ihre Stärke nahmen. Überall in {link:jintha-alor}Jintha'Alor{/link} standen Gefäße mit verdorbenem Blut, durchwoben von Hexx' Magie und erfüllt von der Macht Hakkars. Als die Gefäße gestohlen und gereinigt wurden, ließ der Wahnsinn der Vilebranch nach. Er endete nicht.]=],
		},
		{
			title = "Der Fall der Priesterin",
			hint = "Bringt die Verderbte Priesterin vor Gericht.",
			text = [=[Auf Befehl von {link:primal-torntusk}Primal Torntusk{/link} wurde eine Belohnung für den Tod von Hexx und ihren Aman'zasi-Wachen ausgesetzt. Auch die {link:dwarves}Zwerge{/link} von {link:aerie-peak}Aerie Peak{/link} wollten ihren Tod, denn sie hielt den Schlüssel zu Sharpbeaks Käfig. Die Priesterin fiel auf dem Gipfel ihrer Stadt. Die Vilebranch taumelten unter dem Schlag, und ihre Feinde wussten, dass sie nicht lange führerlos bleiben würden.]=],
		},
	},
	mentions = {
		{ text = "{link:elder-torntusk}Ältester Torntusk{/link} entführt!" },
		{ text = "Dunkle Gefäße" },
		{ text = "Gesucht: Verderbte Priesterin Hexx und ihre Diener" },
		{
			text = [=[Zurück ins {link:the-hinterlands}Hinterland{/link}, das Wort des Wahrsagers]=],
		},
		{ text = "Sharpbeak retten" },
	},
	bonds = {
		{ id = "primal-torntusk", name = "Primal Torntusk", note = "setzte ein Kopfgeld auf sie aus" },
		{ id = "elder-torntusk", name = "Ältester Torntusk", note = "ihr Gefangener" },
		{ id = "sharpbeak", name = "Sharpbeak", note = "ihr Gefangener" },
		{ id = "hitah-ya-the-keeper", name = "Hitah'ya die Hüterin", note = "verwahrt die Schlüssel ihrer Gefangenen" },
	},
})

