Translate("deDE", "shadra", {
	title = "Shadra",
	subtitle = "Die Giftkönigin",
	found = "Herbeigerufen am Altar von Shadra'Alor",
	hint = [=[Erfahrt den wahren Namen des Spinnengottes der Witherbark und sprecht ihn an ihrem Altar.]=],
	allegiance = "Witherbarktrolle",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Shadra ist der Spinnengott der {link:witherbark-trolls}Witherbarktrolle{/link}. Sie nennen sie die Giftkönigin, und von ihr stammt das stärkste Gift, das sie kennen. Sie wandelt nicht unter ihren Anbetern. Sie kommt nur, wenn ihr wahrer Name an ihrem Altar in {link:shadra-alor}Shadra'Alor{/link} laut gelesen wird, und dieser Name ist so schwer von Macht, dass die Weisen ihn nur flüsternd aussprechen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Shadra ist das Herz des Glaubens der {link:witherbark-village}Witherbark{/link}. Ihr Name wurde vor langer Zeit auf eine Tafel in der Trollstadt {red:zul-farrak}Zul'Farrak{/red} geschrieben, weit jenseits des Meeres. Die {link:royal-apothecary-society}Königliche Apothekervereinigung{/link} der Verlassenen begehrt ihr Gift mehr als jedes andere.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie gibt ihr Gift den {link:witherbark-village}Witherbark{/link}, die es in ihren Dörfern in Flaschen aufbewahren.
• Sie wurde an ihrem Altar durch einen Beschwörungszauber herbeigerufen, den {link:master-gadrin}Meister Gadrin{/link} von den {link:darkspear-trolls}Darkspear{/link} verfasst hatte.]=],
		},
	},
	chapters = {
		{
			title = "Die Giftkönigin",
			hint = "Beschwört den Spinnengott in Shadra'Alor.",
			text = [=[{link:apothecary-lydon}Apotheker Lydon{/link} aus {link:tarren-mill}Tarrens Mühle{/link} wollte das frischeste Gift der {link:witherbark-village}Witherbark{/link}, und keine gewöhnliche Spinne genügte. {link:master-gadrin}Meister Gadrin{/link} wusste, woher es stammte. Von einer Tafel in Zul'Farrak kam ihr wahrer Name, und von Gadrin kam ein Pergament, das sie rufen konnte. Am Altar von {link:shadra-alor}Shadra'Alor{/link} wurden die Worte gelesen, und die Giftkönigin antwortete. Ihr Gift ging nach Tarrens Mühle und von dort ins {link:the-apothecarium}Apothekarium{/link} von {link:undercity}Undercity{/link}.]=],
		},
	},
	mentions = {
		{ text = "Giftflaschen" },
		{ text = "Unbeschädigter Giftbeutel" },
		{ text = "Fragt {link:master-gadrin}Meister Gadrin{/link}" },
		{ text = "Der Spinnengott" },
		{ text = "Shadra beschwören" },
		{ text = "Gift für {link:undercity}Undercity{/link}" },
	},
	bonds = {
		{ id = "master-gadrin", name = "Meister Gadrin", note = "schrieb den Zauber, der sie ruft" },
		{ id = "apothecary-lydon", name = "Apotheker Lydon", note = "suchte ihr Gift" },
		{ id = "master-apothecary-faranell", name = "Meisterapotheker Faranell", note = "erhielt ihr Gift" },
	},
})

Translate("deDE", "primal-torntusk", {
	title = "Primal Torntusk",
	subtitle = "Anführerin des Dorfes Revantusk",
	found = "Revantusk",
	hint = "Sprecht mit der Trollin, die das Dorf Revantusk befehligt.",
	allegiance = "Revantusk · Horde",
	aliases = { "Torntusk" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Primal Torntusk befehligt das {link:revantusk-village}Dorf Revantusk{/link}. Ihre Befehle ergehen unter ihrem eigenen Namen, und ihre Kopfgelder sind für alle sichtbar ausgehängt. Sie ist eine Kriegerin der {red:revantusk-trolls}Revantusk{/red} und eine weise Frau ihres Volkes, und sie kennt die dunklen Künste der Vilebranch gut genug, um sie ungeschehen zu machen. Als die Vilebranch in der Nacht kamen und ihren Gefährten fortschleppten, verzweifelte sie nicht. Sie schickte nach Hilfe und zog in den Krieg.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Torntusk hält den Stützpunkt der {link:horde}Horde{/link} im {link:the-hinterlands}Hinterland{/link}. Ihr Dorf ist klein und von Feinden umgeben: den Vilebranch im Norden und Westen, den wilden Tieren der Hügel und den Wildhammern auf der anderen Seite des Landes. Unter ihr sind die {link:revantusk-village}Revantusk{/link} zum hartnäckigsten Feind der Vilebranch geworden. Sie allein unter ihnen scheint zu begreifen, dass der wahre Feind nicht der Stamm ist, sondern der Gott, dem er dient.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie sammelte ihr Dorf, nachdem ein Überfall der Vilebranch ihren Gefährten und ihren Hauptmann der Wache genommen hatte.
• Sie reinigte die Gefäße mit verdorbenem Blut, die aus {link:jintha-alor}Jintha'Alor{/link} fortgeschafft worden waren.
• Sie setzte ein Kopfgeld auf die {link:vile-priestess-hexx}Verderbte Priesterin Hexx{/link} und ihre Aman'zasi-Wache aus.
• Sie sucht einen neuen Hauptmann der Wache als Ersatz für den gefallenen Malkhor.]=],
		},
	},
	chapters = {
		{
			title = "Der Überfall um Mitternacht",
			hint = [=[Rettet den Gefährten der Anführerin der Revantusk aus Jintha'Alor.]=],
			text = [=[Die Vilebranch kamen mitten in der Nacht und nahmen den Ältesten Torntusk lebend mit. Die Späher der {link:revantusk-village}Revantusk{/link} erfuhren, dass er auf dem Gipfel von {link:jintha-alor}Jintha'Alor{/link} festgehalten wurde und dass {link:vile-priestess-hexx}Hexx{/link} ihn {link:hakkar}Hakkar{/link} opfern wollte. Torntusk sagte offen, dass ihr Dorf einen solchen Verlust nicht ertragen könne. Die Fesseln wurden gebrochen, der Älteste kehrte heim, und die Schuld der Revantusk war groß.]=],
		},
		{
			title = "Den Griff lockern",
			hint = [=[Stehlt die verdorbenen Gefäße von Jintha'Alor für Primal Torntusk.]=],
			text = [=[Torntusk begriff, dass die Vilebranch nicht mit ihrer eigenen Kraft kämpften. Das Blut in ihren Gefäßen trug die Macht des gesichtslosen Gottes in sich, und es trieb sie in den Wahnsinn. Als man ihr die Gefäße brachte, zog sie die Verderbnis aus ihnen heraus. Der Griff des Blutgottes lockerte sich. Sie warnte ihr Volk, dass es nur für eine Weile sei.]=],
		},
		{
			title = "Ein Hauptmann für Revantusk",
			hint = [=[Erweist Euch des Postens des Hauptmanns der Wache von Revantusk würdig.]=],
			text = [=[Mit Malkhors Tod stand der Posten des Hauptmanns der Wache leer. Torntusk rief jeden auf, der die Reihen der Krieger, Schattenjäger, Bluttrinker und Seelenfresser der Vilebranch lichten würde. Wer dem Ruf folgte, erhielt Dank und Lohn. Die Wahl selbst, sagte sie, werde bis zum nächsten Jahr warten.]=],
		},
	},
	mentions = {
		{ text = "{link:elder-torntusk}Ältester Torntusk{/link} entführt!" },
		{ text = "Zurück zu Primal Torntusk" },
		{ text = "Dunkle Gefäße" },
		{
			text = [=[Gesucht: {link:vile-priestess-hexx}Verderbte Priesterin Hexx{/link} und ihre Diener]=],
		},
		{
			text = [=[Stelle frei: Hauptmann der Wache von {link:revantusk-village}Revantusk{/link}]=],
		},
	},
	bonds = {
		{ id = "elder-torntusk", name = "Ältester Torntusk", note = "ihr Gefährte" },
		{ id = "huntsman-markhor", name = "Waidmann Markhor", note = "Bruder ihres gefallenen Hauptmanns" },
		{ id = "vile-priestess-hexx", name = "Verderbte Priesterin Hexx", note = "ihre Feindin" },
		{ id = "falstad-wildhammer", name = "Falstad Wildhammer", note = "Than der Zwerge, die ihr Volk hasst" },
	},
})

