Translate("deDE", "smith-slagtree", {
	title = "Schmied Slagtree",
	subtitle = "Schmied von Revantusk",
	found = "Revantusk",
	hint = "Sucht den Orcschmied des Dorfes Revantusk.",
	allegiance = "Revantusk · Horde",
	aliases = { "Slagtree" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Schmied Slagtree ist ein {link:orcs}Orc{/link}, der die Schmiede des Dorfes {link:revantusk-village}Revantusk{/link} betreibt. Als die Vilebranch das Dorf überfielen, stahlen sie sein Werkzeug. Es war nicht irgendein Werkzeug. Es war das Geschenk eines freundlichen Gnoms, der ihm einst das Leben rettete, als Slagtree ein junger Orc war.]=],
		},
